<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Workforce Administration · Atlas</title><link rel="stylesheet" href="<?=esc(url_for('assets/app.css'))?>"></head><body class="standalone-with-nav"><?=standaloneSidebar($navGroups,'team',$admin,$org,$user,$location)?><main class="page-wrap standalone-workspace"><header class="page-header"><div><p class="eyebrow">WORKFORCE ADMINISTRATION</p><h1><?=esc($profile['name'])?></h1><p>Employment lifecycle, secondary assignments, onboarding, restricted notes, and profile history.</p></div><form method="get"><input type="hidden" name="route" value="employee-admin"><select name="membership_id" onchange="this.form.submit()"><?php foreach($data['people'] as $person):?><option value="<?=$person['membership_id']?>" <?=$person['membership_id']===$selectedEmployeeId?'selected':''?>><?=esc($person['name'])?></option><?php endforeach;?></select></form></header><?php if($notice):?><div class="page-flash <?=$notice['type']?>"><span>✓</span><?=esc($notice['message'])?></div><?php endif;?><?php if($error):?><div class="form-alert error"><?=esc($error)?></div><?php endif;?><section class="planning-grid"><article class="panel"><h2>Employment lifecycle</h2><form method="post" class="stack-form"><?=Csrf::field()?><input type="hidden" name="action" value="save_employment_record"><input type="hidden" name="membership_id" value="<?=$selectedEmployeeId?>"><label>Status<select name="employment_status"><?php foreach(['preboarding','active','leave','ended'] as $status):?><option value="<?=$status?>" <?=($employment['employment_status']??'active')===$status?'selected':''?>><?=esc(ucfirst($status))?></option><?php endforeach;?></select></label><label>Start date<input type="date" name="starts_on" value="<?=esc($employment['starts_on']??'')?>"></label><label>End date<input type="date" name="ends_on" value="<?=esc($employment['ends_on']??'')?>"></label><label>Separation note<input name="separation_reason" value="<?=esc($employment['separation_reason']??'')?>"></label><button class="button primary">Save and snapshot</button></form></article><article class="panel"><h2>Secondary assignment</h2><form method="post" class="stack-form"><?=Csrf::field()?><input type="hidden" name="action" value="add_secondary_assignment"><input type="hidden" name="membership_id" value="<?=$selectedEmployeeId?>"><label>Location<select name="location_id"><option value="">None</option><?php foreach($data['locations'] as $item):?><option value="<?=$item['id']?>"><?=esc($item['name'])?></option><?php endforeach;?></select></label><label>Department<select name="department_id"><option value="">None</option><?php foreach($data['departments'] as $item):?><option value="<?=$item['id']?>"><?=esc($item['name'])?></option><?php endforeach;?></select></label><label>Position<select name="position_id"><option value="">None</option><?php foreach($data['positions'] as $item):?><option value="<?=$item['id']?>"><?=esc($item['name'])?></option><?php endforeach;?></select></label><label>Effective from<input type="date" name="effective_from"></label><label>Effective through<input type="date" name="effective_to"></label><button class="button primary">Add assignment</button></form><?php foreach($workforceAdmin['assignments'] as $item):?><div class="planning-row"><span><strong><?=esc($item['position_name']?:'Additional assignment')?></strong><small><?=esc(($item['location_name']?:'Any location').' · '.($item['department_name']?:'Any department'))?></small></span></div><?php endforeach;?></article><article class="panel"><h2>Restricted manager notes</h2><form method="post" class="stack-form"><?=Csrf::field()?><input type="hidden" name="action" value="add_manager_note"><input type="hidden" name="membership_id" value="<?=$selectedEmployeeId?>"><label>Operational note<textarea name="note_text" rows="4" maxlength="2000" required></textarea></label><button class="button primary">Add restricted note</button></form><?php foreach($workforceAdmin['notes'] as $item):?><div class="planning-row"><span><strong><?=esc($item['author_name'])?></strong><small><?=esc($item['created_at'])?></small><p><?=esc($item['note_text'])?></p></span></div><?php endforeach;?></article><article class="panel"><h2>Onboarding checklist</h2><form method="post" class="stack-form"><?=Csrf::field()?><input type="hidden" name="action" value="add_onboarding_item"><input type="hidden" name="membership_id" value="<?=$selectedEmployeeId?>"><label>Item<input name="item_name" required></label><label>Due date<input type="date" name="due_on"></label><button class="button primary">Add item</button></form><?php foreach($workforceAdmin['onboarding'] as $item):?><div class="planning-row"><span><strong><?=esc($item['item_name'])?></strong><small><?=esc(($item['due_on']?'Due '.$item['due_on']:'No due date').($item['completed_at']?' · Completed':''))?></small></span><form method="post"><?=Csrf::field()?><input type="hidden" name="action" value="complete_onboarding_item"><input type="hidden" name="membership_id" value="<?=$selectedEmployeeId?>"><input type="hidden" name="item_id" value="<?=$item['id']?>"><button class="button secondary"><?=$item['completed_at']?'Reopen':'Complete'?></button></form></div><?php endforeach;?></article><article class="panel span-2"><h2>Profile snapshots</h2><?php foreach($workforceAdmin['snapshots'] as $item):?><div class="planning-row"><span><strong><?=esc(ucwords(str_replace('_',' ',$item['snapshot_type'])))?></strong><small><?=esc($item['created_at'])?></small></span></div><?php endforeach;?><?php if(!$workforceAdmin['snapshots']):?><div class="inline-empty"><strong>No snapshots yet</strong></div><?php endif;?></article></section></main></body></html>
